for (const operation of operations) {
    if (Object.hasOwn(operation, 'create')) {
        if (fs.existsSync(operation.path) && fs.readFileSync(operation.path, 'utf8') !== operation.create) throw new Error('Unexpected existing source: ' + operation.path);
        fs.writeFileSync(operation.path, operation.create);
        continue;
    }
    const source = fs.readFileSync(operation.path, 'utf8');
    if (source.includes(operation.after)) continue;
    if (!source.includes(operation.before)) {
        throw new Error('Missing 0.4.7 transformation anchor: ' + operation.path);
    }
    fs.writeFileSync(operation.path, source.replace(operation.before, operation.after));
}
